"""Build both printable summaries from shared copy and the saved evaluation. No model calls."""
import json
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
saved = json.loads((ROOT / "eval-results.js").read_text(encoding="utf-8").removeprefix("window.EVAL_RESULTS = ").strip().removesuffix(";"))
summary = saved["summary"]
checks = summary["all_checks_passed"]
emergencies = summary["emergency_recall"]
role = "Digital Operations &amp; AI Automation"
contact = '<a href="mailto:adamjskoog@gmail.com?subject=SSPros%20role%20conversation">adamjskoog@gmail.com</a> · <a href="tel:+18056240580">805-624-0580</a>'
assignment = "One new service page for your website, built from facts you approve, with customer requests going straight to the right person. It would be my first piece of work in the role, finished and checked within the first 30 days."
responsibilities = "<ul><li>Keep website wording, facts, and pages current.</li><li>Keep records of customer requests, draft replies, and follow-up reminders.</li><li>Test and maintain approved AI tools, with people reviewing the outputs.</li><li>Write short instructions and provide a weekly progress update.</li></ul>"
plan = '<div class="phase-lines"><p><strong>Days 1–30 · Learn and deliver</strong><br>Finish the first service page, learn how customer requests move through the office, and measure how long it takes today.</p><p><strong>Days 31–60 · Own and test</strong><br>Own website updates and follow-up preparation. Test the AI tool on real company emails, with names and contact details removed, against checks we agree on.</p><p><strong>Days 61–90 · Compare and decide</strong><br>If the test goes well, try it on a small number of new requests, with a person approving every reply. Compare time, quality, and cost, then decide whether to expand, adjust, or stop.</p></div>'
pay = '<h2>Pay and hours</h2><p>Open to discussion. I’m looking for a way into this kind of work, not top pay, and I’m glad to start part-time and grow the role as I prove useful.</p>'
costs_short = '<h2>Tool costs and ownership</h2><p>The company provides and pays for <strong>Claude Max</strong> and <strong>ChatGPT Pro with Codex</strong> ($200 tier each): <strong>$400 a month at most</strong>, with no extra credits or usage fees. Everything I build stays in company accounts.</p>'
decision = '<div class="ask"><h2>The decision to make together</h2><p>Choose a first assignment, agree paid hours and compensation, name a manager and approver, and set a delivery date and first review. A 30-minute conversation is the next step.</p></div>'
costs = '<h2>Tool costs: $400 a month, never more</h2><p>The company provides and pays for two AI accounts in its own name: <strong>Claude Max ($200 tier)</strong> and <strong>ChatGPT Pro with Codex ($200 tier)</strong>. No pay-as-you-go credits, add-ons, or usage fees; those settings stay off. If a limit is reached, the work waits or is done by hand. Any change needs written approval.</p>'
ownership = '<h2>Everything I build belongs to the company</h2><p>Website changes, templates, and tools stay in company accounts. If the role ends, I hand everything over with written notes.</p>'
limit = "I wrote the test emails myself, so real emails may go differently. Nothing is sent automatically. A person reads and approves every reply."

def page(title, content):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Adam Skoog · {escape(title)}</title><link rel="icon" href="mark.svg" type="image/svg+xml"><link rel="stylesheet" href="brief.css"></head><body><nav class="tools" aria-label="Document actions"><a href="index.html">← Back to the proposal</a><button onclick="window.print()" type="button">Print / save PDF</button></nav><main class="page">{content}</main></body></html>'''

identity = f'<p class="eyebrow">Prepared for System Solutions Pros · November 2026</p><p class="author"><strong>Adam Skoog</strong> · {contact}</p>'
evidence = f'<p>I tested the tool on {summary["cases"]} made-up customer emails. <strong>It passed every check on {checks["passed"]} of {checks["total"]}</strong>, sent all {emergencies["passed"]} of {emergencies["total"]} emergencies straight to a person, and had {summary["unsafe_drafts"]} replies flagged as a problem. The proposal website shows exactly what it wrote.</p>'
brief = f'''<section class="brief-sheet">{identity}<h1>{role}</h1><p class="lead">A clearer website, better follow-up, and useful tools I can build and maintain.</p><p>I’m proposing a paid role owning website updates, follow-up preparation, and practical AI tools. I’m new to the electrical trade; your team brings that knowledge, and I’d start by learning your process.</p><h2>About me</h2><p>After earning a computer science degree, I worked for two and a half years as a WordPress developer at Clearwater, building marketing websites. When COVID hit, I started driving for DoorDash, and I’ve done that for the past four years. Now I want to get back into this kind of work and grow with a team.</p><h2>Start with one useful assignment</h2><p>{assignment}</p>{pay}<h2>Work you can inspect</h2><p>Using AI tools, I built a sample commercial service page, a tool that sorts customer emails and drafts replies, a review of the current website, eight blank office templates, and this proposal.</p>{evidence}<p class="small">{limit}</p></section><section class="brief-sheet"><h2 class="sheet-title">The first 90 days</h2>{plan}<h2>What I would own</h2>{responsibilities}{costs}{ownership}<h2>How we would judge the work</h2><p>How quickly customers hear back, whether requests arrive with the details you need, whether every request has someone responsible and a next step, and staff time per email. Any time savings must count the time spent checking and fixing.</p>{decision}<p class="author">Adam Skoog · {contact}</p><p class="small">Independent hiring proposal. Example messages are fictional, and the demonstration does not connect to company systems.</p></section>'''
role_summary = f'''<section class="brief-sheet">{identity}<h1>{role}</h1><p class="lead">A paid role owning website updates, customer follow-up preparation, and carefully tested tools.</p><h2>First assignment</h2><p>{assignment}</p>{pay}<h2>Ongoing responsibilities</h2>{responsibilities}<h2>Review points</h2><p><strong>Day 30:</strong> review the finished page and how requests are handled today. <strong>Day 60:</strong> review ongoing duties and test results on real emails. <strong>Day 90:</strong> compare any trial with where we started and agree the ongoing role.</p>{costs_short}{decision}<p class="small">Independent proposal · prepared by Adam Skoog using AI tools. No demonstration connects to company systems.</p></section>'''
(ROOT / "brief.html").write_text(page("Decision brief", brief), encoding="utf-8")
(ROOT / "role-summary.html").write_text(page("Role summary", role_summary), encoding="utf-8")
print("Built brief.html and role-summary.html from shared copy and saved evaluation.")
